import React from 'react';
import { onKeyEnter } from '../../utils/utils';
import Styled from './PageSlot.styles';

const PageSlot = ({
  label,
  disabled,
  isSelected,
  handlePageChange,
}: {
  label: string;
  disabled: boolean;
  isSelected: boolean;
  handlePageChange: (pageNumber: number) => void;
}): JSX.Element => {
  const PageElement = isSelected ? 'span' : 'a';
  const pageElementProps = isSelected
    ? {
        'aria-label': `Current Page, Page ${Number(label)}`,
        'aria-current': true,
      }
    : {
        'aria-label': `go to page ${Number(label)}`,
        rel: 'nofollow',
        'aria-disabled': disabled ? true : undefined,
      };
  return (
    <Styled.Container
      onClick={() => handlePageChange(Number(label))}
      onKeyDown={(e: React.KeyboardEvent<HTMLLIElement>) =>
        onKeyEnter(e, () => handlePageChange(Number(label)))
      }
      disabled={disabled}
      isSelected={isSelected && !disabled}
      tabIndex={disabled ? -1 : 0}
      title={`page ${label}`}
    >
      <PageElement {...pageElementProps}>{label}</PageElement>
    </Styled.Container>
  );
};

export default PageSlot;
